def dict_merge(dicts):
    """
    Combine dictionaries to keys which map to multiple values
    """
    keys = set(dicts[0].keys())
    for d in dicts[1:]:
        keys = keys.union(d.keys())
    return [d.get(key, None) for key in keys]


